/* geteuid/getegid for OS-9/68k. * * OS-9 has no set-user-id bit and so no real-vs-effective user distinction: * a process runs as whoever forked it. clib supplies getuid(); geteuid() is in * no library on this system. getgid() is absent too.  getuid() returns F$ID's * whole group.user word -- 0x00010007 for 1.7 -- so the group is its high * half, as blarslib's getgid() has it.  (Until 2026-09-24 this returned 0 * and the comment said otherwise; no program built with it then used it.) */extern int getuid();int geteuid(){    return getuid();}int getegid(){    return (int)((unsigned)getuid() >> 16);}int getgid(){    return (int)((unsigned)getuid() >> 16);}/* unix_getuid -- gtar names.c calls it under #ifdef OSK, where every other   arm calls getuid().  The OSK porter had one; nothing here does.  Same   thing under a different name. */intunix_getuid(){    return getuid();}